// IQ1SGrid is shared by IQ1_S and IQ1_M decoding.
var IQ1SGrid [2048]uint64
var IQ2XXSGrid [256]uint64
var IQ2XSGrid [512]uint64
var IQ3XXSGrid [256]uint32

func init() {
	iq1sRaw, err := base64.StdEncoding.DecodeString(iq1sGridBase64)
	if err != nil || len(iq1sRaw) != 16384 {
		panic("invalid embedded IQ1_S/IQ1_M codebook")
	}
	if sha256.Sum256(iq1sRaw) != iq1sGridSHA256 {
		panic("embedded IQ1_S/IQ1_M codebook checksum mismatch")
	}
	for i := range IQ1SGrid {
		IQ1SGrid[i] = binary.LittleEndian.Uint64(iq1sRaw[i*8:])
	}

	iq2xxsRaw, err := base64.StdEncoding.DecodeString(iq2xxsGridBase64)
	if err != nil || len(iq2xxsRaw) != 2048 {
		panic("invalid embedded IQ2_XXS codebook")
	}
	if sha256.Sum256(iq2xxsRaw) != iq2xxsGridSHA256 {
		panic("embedded IQ2_XXS codebook checksum mismatch")
	}
	for i := range IQ2XXSGrid {
		IQ2XXSGrid[i] = binary.LittleEndian.Uint64(iq2xxsRaw[i*8:])
	}

	iq2xsRaw, err := base64.StdEncoding.DecodeString(iq2xsGridBase64)
	if err != nil || len(iq2xsRaw) != 4096 {
		panic("invalid embedded IQ2_XS codebook")
	}
	if sha256.Sum256(iq2xsRaw) != iq2xsGridSHA256 {
		panic("embedded IQ2_XS codebook checksum mismatch")
	}
	for i := range IQ2XSGrid {
		IQ2XSGrid[i] = binary.LittleEndian.Uint64(iq2xsRaw[i*8:])
	}

	iq3xxsRaw, err := base64.StdEncoding.DecodeString(iq3xxsGridBase64)
	if err != nil || len(iq3xxsRaw) != 1024 {
		panic("invalid embedded IQ3_XXS codebook")
	}
	if sha256.Sum256(iq3xxsRaw) != iq3xxsGridSHA256 {
		panic("embedded IQ3_XXS codebook checksum mismatch")
	}
	for i := range IQ3XXSGrid {
		IQ3XXSGrid[i] = binary.LittleEndian.Uint32(iq3xxsRaw[i*4:])
	}
}
